#!/usr/bin/env bash
# GENERATED by build_app.py for tenant "in.localappstore.fieldcrm.demo"
# One-command iOS archive + IPA export. Run this on macOS with Xcode installed.
set -euo pipefail

cd "$(dirname "$0")"

WORKSPACE="ios/App/App.xcworkspace"
SCHEME="App"
CONFIG="Release"
ARCHIVE_PATH="build/in.localappstore.fieldcrm.demo-1.0.0-1.xcarchive"
IPA_PATH="build/ipa"
EXPORT_OPTIONS="/Users/wafutechnologies/Documents/Projects/field-crm/output/demo/ExportOptions.plist"

echo "▶ Cleaning previous archives"
rm -rf build && mkdir -p build

echo "▶ Archiving (Release, iphoneos)"
xcodebuild archive \
  -workspace "$WORKSPACE" \
  -scheme "$SCHEME" \
  -configuration "$CONFIG" \
  -destination "generic/platform=iOS" \
  -archivePath "$ARCHIVE_PATH" \
  -allowProvisioningUpdates \
  MARKETING_VERSION="1.0.0" \
  CURRENT_PROJECT_VERSION="1"

if [ ! -f "$EXPORT_OPTIONS" ]; then
  echo "⚠ ExportOptions.plist not found at $EXPORT_OPTIONS — stopping after archive."
  echo "  Open the .xcarchive in Xcode → Window → Organizer → Distribute App."
  exit 0
fi

echo "▶ Exporting IPA"
xcodebuild -exportArchive \
  -archivePath "$ARCHIVE_PATH" \
  -exportOptionsPlist "$EXPORT_OPTIONS" \
  -exportPath "$IPA_PATH" \
  -allowProvisioningUpdates

IPA=$(find "$IPA_PATH" -name "*.ipa" | head -n 1)
echo ""
echo "✅  IPA ready: $IPA"
